    if (context != null && !fieldsNotFound.isEmpty()) {
        if (headers.length == 0) {
            throw new DataProcessingException("Could not find fields " + fieldsNotFound.toString() + " in input. Please enable header extraction in the parser settings in order to match field names.");
        }
        if (strictHeaderValidationEnabled) {
            DataProcessingException exception = new DataProcessingException("Could not find fields " + fieldsNotFound.toString() + " in input. Names found: " + Arrays.toString(headers));
            throw exception;
        }
